input.command:
npx ngc -p tsconfig.json --noEmit 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | grep -E "^src.*TS2339: Property 'disableTooltip'" | sed -E 's/^([^:]+):([0-9]+):([0-9]+).*/\1 \2 \3/' > /tmp/e.txt
node -e '
const fs=require("fs");const L=fs.readFileSync("/tmp/e.txt","utf8").trim().split("\n").map(l=>l.split(" "));
L.sort((a,b)=>b[2]-a[2]);
for(const [f,l,c] of L){const t=fs.readFileSync(f,"utf8").split("\n");const s=t[l-1];if(s.substr(c-1,14)!=="disableTooltip")throw f;t[l-1]=s.slice(0,c-1)+"hideHint"+s.slice(c-1+14);fs.writeFileSync(f,t.join("\n"));}
console.log(L.length)'
npx ngc -p tsconfig.json; echo rc=$?

